
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m06_hf_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m06_hf", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.384907833544832e-01, -1.366720585507608e-01, -1.340127249148661e-01, -1.300951736036609e-01, -1.242609105804407e-01, -1.154343845884104e-01, -1.017870204156106e-01, -8.012846912848151e-02, -4.527704894537148e-02, 5.476579578159048e-03, 1.657158477263959e-02, -7.367630649405403e-02, -4.200681584743082e-02, -3.905648478195467e-02, 1.085590089609777e-03, 3.153605829749877e-02, -3.883857761410215e-02, -2.507726103786163e-02, -3.162237721218042e-03, -1.392412852679853e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


